@extends('layouts.app') @section('title','Your Bag — Apex Market') @section('content')<section class="page"><p class="eyebrow">Your selection</p><h1>Shopping bag</h1>@if($cart['items']->isEmpty())<div class="empty"><h2>Your bag is empty.</h2><p>Discover something made to last.</p><a class="button" href="{{route('store.index')}}">Start shopping</a></div>@else<div class="cart-layout"><div>@foreach($cart['items'] as $item)<article class="cart-item"><img src="{{$item['product']->image_url}}" alt=""><div><p>{{$item['product']->category->name}}</p><h3>{{$item['product']->name}}</h3><strong>${{number_format($item['line_total']/100,2)}}</strong></div><form method="post" action="{{route('cart.update',$item['product'])}}">@csrf @method('PATCH')<label>Qty<input name="quantity" type="number" min="0" max="10" value="{{$item['quantity']}}"></label><button>Update</button></form><form method="post" action="{{route('cart.destroy',$item['product'])}}">@csrf @method('DELETE')<button class="text-button">Remove</button></form></article>@endforeach</div><aside class="summary"><h2>Order summary</h2><p><span>Subtotal</span><b>${{number_format($cart['subtotal']/100,2)}}</b></p><p><span>Shipping</span><b>{{$cart['shipping']?'$'.number_format($cart['shipping']/100,2):'Free'}}</b></p><hr><p class="total"><span>Total</span><b>${{number_format($cart['total']/100,2)}} CAD</b></p><a class="button" href="{{route('checkout.create')}}">Continue to checkout</a><small>Taxes calculated at checkout.</small></aside></div>@endif</section>@endsection
